WITH metrics AS (SELECT *, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY segment), 4) credit_limit_share, FIRST_VALUE(city) IGNORE NULLS OVER w_hist first_known_city, NTILE(5) OVER (PARTITION BY YEAR(signup_date), city ORDER BY age, id) age_bucket FROM customers WHERE email LIKE '%@startup.io' WINDOW w_hist AS (PARTITION BY city ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, name, email, country, city, signup_date, is_active, age, credit_limit_share, CASE WHEN name RLIKE '^(David Lee |Alice Wong)$' THEN 'GROUP_B' WHEN name RLIKE '^(bob smith|  Carol Diaz)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS name_zone FROM metrics ORDER BY city DESC, country;
